import json,csv
from pathlib import Path
p=Path('reports/winspace-2026-10-31');a=json.loads((p/'final-actions.json').read_text());c=json.loads((p/'coverage.json').read_text());after=json.loads((p/'after.json').read_text());by={x['id']:x for x in after}
lines=['# Winspace calendar review — 31 October 2026','','Source: https://kalendar.winspace.cz/kalendar','','Scope: all 95 upcoming entries visible in the supplied calendar (31 October 2026–2 October 2027). The historical toggle was not part of this audit.','','## Published database changes','','- One new separate 2027 edition: Předvýběr.CZ Bike Maraton Vysočina, 29 May 2027, Kněžice. Stable venue and provisional age groups come from the verified 2026 record; age_confidence = previous. No detailed old categories, fees, registrations or schedules copied.','- Twelve previously hidden records published, including the Trnava–Rysy ride (retained as ride). Together with the new edition: 12 more races plus one ride.','- Existing Prague track cup dates and Šamorín race title repaired.','- 15 events outside the seven current public countries have corrected countries, places, dates and source links, and remain hidden pending a country-coverage decision.','- 31 canonical events reviewed/written in total, plus one duplicate merged; 91 of the 95 source entries map to 89 existing or newly created events because Sudety Tour has three source entries for one weekend.','','## Exclusions and unresolved evidence','','| Source entry | Reason |','| --- | --- |']
for x in c:
 if x['outcome']=='excluded':lines.append(f"| [{x['name']}]({x['source']}) | {x['reason']} |")
lines+=['','','The Bike Attack row already exists hidden; it was not promoted as a cycling race. SauwaldGiro 2027 has not been created from an uncorroborated aggregator date. The organiser page still gives 30 August 2026: https://www.sauwaldgiro.at/.','','Mamut Tour: organiser confirms 22 May 2027 in Prosenice and timed 132/80 km routes; erroneous 23 May record repaired and duplicate 80 km record merged. https://miko-cycles.cz/mamut/mamut-tour/propozice/', '', '## Outside current public coverage','','| Event | Date | Country |','| --- | --- | --- |']
for x in a:
 if x['patch']['visibility']=='hidden':lines.append(f"| {x['patch']['name']} | {x['patch']['start_date']} | {x['country']} |")
lines+=['','','## Verification','','The initial 30 writes and the additional Mamut Tour repair were read back and compared with the reviewed manifest. All 75 race source entries expected in the seven-country public calendar were found in the live public feed (74 unique events, since Sudety Tour has three entries and Trnava–Rysy remains a ride). Public map/list/catalogue refresh requested through an authenticated existing admin action. No application taxonomy or country expansion shipped.','','The complete mapping is in coverage.csv; source snapshots, before/after backups and field evidence remain in this directory. Database writes are recorded in apply.sql, refinements.sql and mamut.sql; import provenance is saved in event_facts with version winspace-review-2026-10-31-v1.','','Release note: Czech and English note added for 31 October 2026. Deployment verification is recorded separately.']
# compute actual unique counts rather than narrative guesses
checks=json.loads((p/'public-checks.json').read_text());expected=[x for x in checks if x['expected']];lines=[l.replace('75 race source entries',f'{len(expected)} race source entries').replace('74 unique events',f'{len(set(x["id"] for x in expected))} unique events') for l in lines]
(p/'REPORT.md').write_text('\n'.join(lines)+'\n')
with (p/'coverage.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['index','source_name','source_url','event_id','outcome','country','visibility','reason']);
 for x in c:
  e=by.get(x.get('id'),{});w.writerow([x['index'],x['name'],x['source'],x.get('id'),x['outcome'],e.get('location',{}).get('country_code'),e.get('visibility'),x.get('reason','')])
print('expected source entries',len(expected),'unique',len(set(x['id'] for x in expected)))
